// devices.device.setVersions and devices.firmwareIssue.record — D-31. Generated by `pnpm gen:command`; the
// acceptance cases follow a device from entered versions to a known issue shown on its project.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  Forbidden,
  grantOf,
  NotFound,
  openTestKernel,
  ValidationFailed,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { recordFirmwareIssue } from '../commands/record-firmware-issue.ts';
import { registerDevice } from '../commands/register-device.ts';
import { setVersions } from '../commands/set-versions.ts';
import { siteDevices } from '../queries/site-devices.ts';

const pm = aStaffActor({ roles: ['pm'] });
const rnd = aStaffActor({ roles: ['rnd'] });
let testDb: TestDatabase;
let t: TestKernel;
let siteA: string;
let siteB: string;
const ids: string[] = [];
const set = (input: Record<string, unknown>) =>
  t.kernel.execute(setVersions, pm, { siteId: siteA, deviceIds: ids, ...input }, 'test');

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  const setup = aStaffActor({ roles: ['director'] });
  t.grant(setup, createClient.permission, createSite.permission);
  t.grant(pm, setVersions.permission, registerDevice.permission, siteDevices.permission);
  t.grant(rnd, recordFirmwareIssue.permission);
  const a = await t.kernel.execute(createClient, setup, { shortCode: 'CLIENTA', name: 'Client A' }, 'test');
  const place = { countryCode: 'ES', cityCode: 'MAD', cityName: 'Madrid', name: 'Mall A', standard: 'L' };
  ({ id: siteA } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
  ({ id: siteB } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
  for (const sn of ['SN-0001', 'SN-0002']) {
    ids.push((await t.kernel.execute(registerDevice, pm, { siteId: siteA, sn, model: 'G6' }, 'test')).id);
  }
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('D-31 firmware and algorithm versions', () => {
  it('versions are for directors, PMs and R&D; issues for directors and R&D', async () => {
    expect(grantOf(setVersions.permission)?.roles).toEqual(['director', 'pm', 'rnd']);
    expect(grantOf(recordFirmwareIssue.permission)?.roles).toEqual(['director', 'rnd']);
    await expect(
      t.kernel.execute(
        recordFirmwareIssue,
        pm,
        { model: 'G6', firmware: '1', summary: 'x', severity: 'info' },
        'test',
      ),
    ).rejects.toBeInstanceOf(Forbidden);
  });

  it('refuses nothing to set, a device of another project and an unknown project', async () => {
    await expect(set({})).rejects.toBeInstanceOf(ValidationFailed);
    await expect(set({ siteId: siteB, firmware: '3.2.1' })).rejects.toBeInstanceOf(NotFound);
    await expect(set({ deviceIds: [...ids, randomUUID()], firmware: '3.2.1' })).rejects.toBeInstanceOf(
      ValidationFailed,
    );
  });

  it('sets the versions on many devices at once; the audit keeps the old values', async () => {
    expect(await set({ firmware: '3.2.1', algorithmVersion: 'ff-2.4' })).toEqual({ updated: 2 });
    expect(
      await countRows(testDb.url, `device WHERE firmware = '3.2.1' AND algorithm_version = 'ff-2.4'`),
    ).toBe(2);
    expect(await countRows(testDb.url, 'audit_event WHERE command = $1', [setVersions.name])).toBe(1);
  });

  it('a known issue of that model and firmware shows on every matching device of the project', async () => {
    await t.kernel.execute(
      recordFirmwareIssue,
      rnd,
      {
        model: 'g6',
        firmware: '3.2.1',
        summary: 'Counts drop after 72 h uptime',
        severity: 'degraded',
        source: 'RN-3.2.2',
      },
      'test',
    );
    await t.kernel.execute(
      recordFirmwareIssue,
      rnd,
      { model: 'G6', firmware: '3.1.0', summary: 'Older problem', severity: 'info' },
      'test',
    );
    const list = await t.kernel.read(siteDevices, pm, { siteId: siteA });
    expect(list.map((d) => [d.firmware, d.algorithmVersion, d.firmwareIssues.map((x) => x.summary)])).toEqual(
      [
        ['3.2.1', 'ff-2.4', ['Counts drop after 72 h uptime']],
        ['3.2.1', 'ff-2.4', ['Counts drop after 72 h uptime']],
      ],
    );
  });
});
